48	        uint256 arbiAmount = dogeAmount / rate;
49	        // Integer division truncates toward zero, so a dogeAmount smaller than
50	        // `rate` would otherwise let the DEX take the user's dogeFake while
51	        // paying out zero arbiFake in return.
52	        require(arbiAmount > 0, "Amount too small to swap");
53	
54	        require(arbiFake.balanceOf(address(this)) >= arbiAmount, "Not enough arbiFake in DEX");
